import { getValidMercadoPagoStoreAccessToken, mercadoPagoStoreRequest } from '../integrations/mercadoPagoStoreOauthService.js';

type MercadoPagoPayment = {
  id?: unknown;
  status?: unknown;
  status_detail?: unknown;
  collector_id?: unknown;
  transaction_amount?: unknown;
  date_approved?: unknown;
  currency_id?: unknown;
  external_reference?: unknown;
};

/**
 * Fetches a payment directly from the seller's OAuth account.
 * The expected reference must be generated by trusted checkout code, not the browser.
 */
export const verifyPrepaidRenewalMercadoPagoPayment = async (input: {
  sellerCredentialScopeId: string;
  paymentId: string;
  expectedExternalReference: string;
  expectedAmountMinor: number;
}) => {
  if (typeof input.paymentId !== 'string' || !/^\d{1,32}$/.test(input.paymentId) ||
      typeof input.sellerCredentialScopeId !== 'string' ||
      !input.sellerCredentialScopeId || input.sellerCredentialScopeId.length > 180 ||
      input.sellerCredentialScopeId.includes('/') ||
      typeof input.expectedExternalReference !== 'string' ||
      !input.expectedExternalReference || input.expectedExternalReference.length > 180 ||
      !Number.isSafeInteger(input.expectedAmountMinor) || input.expectedAmountMinor <= 0) {
    throw new Error('INVALID_RENEWAL_PAYMENT_LOOKUP');
  }
  // OAuth identifies the expected merchant, but the payment itself must also
  // confirm that merchant as collector; a token scope alone is insufficient.
  const sellerToken = await getValidMercadoPagoStoreAccessToken(input.sellerCredentialScopeId);
  const expectedCollectorId = String(sellerToken.externalAccountId ?? '');
  if (!/^\d+$/.test(expectedCollectorId)) {
    throw new Error('RENEWAL_SELLER_ACCOUNT_NOT_VERIFIED');
  }
  const payment = await mercadoPagoStoreRequest<MercadoPagoPayment>(
    input.sellerCredentialScopeId, `/v1/payments/${input.paymentId}`
  );
  const amount = payment.transaction_amount;
  const rawMinor = typeof amount === 'number' && Number.isFinite(amount)
    ? amount * 100 : NaN;
  const amountMinor = Number.isSafeInteger(Math.round(rawMinor)) &&
    Math.abs(rawMinor - Math.round(rawMinor)) < 1e-6
    ? Math.round(rawMinor) : NaN;
  if (String(payment.id) !== input.paymentId ||
      payment.status !== 'approved' ||
      payment.status_detail !== 'accredited' ||
      (typeof payment.collector_id !== 'number' && typeof payment.collector_id !== 'string') ||
      !/^\d+$/.test(String(payment.collector_id)) ||
      String(payment.collector_id) !== expectedCollectorId ||
      payment.currency_id !== 'BRL' ||
      payment.external_reference !== input.expectedExternalReference ||
      amountMinor !== input.expectedAmountMinor ||
      typeof payment.date_approved !== 'string' ||
      !/^\d{4}-\d{2}-\d{2}T/.test(payment.date_approved) ||
      !Number.isFinite(Date.parse(payment.date_approved))) {
    throw new Error('RENEWAL_PROVIDER_PAYMENT_MISMATCH');
  }
  return {
    id: input.paymentId,
    status: 'approved',
    amountMinor,
    occurredAt: new Date(payment.date_approved).toISOString(),
    verifiedByProvider: true as const,
  };
};
